def parse_matrix(s):
    return json.loads(s)

def connected(adj, src, dst):
    n = len(adj)
    if src == dst:
        return True
    if src < 0 or src >= n or dst < 0 or dst >= n:
        return False
    seen = [False]*n
    stack = [src]
    seen[src] = True
    while stack:
        u = stack.pop()
        for v in range(n):
            if adj[u][v] and not seen[v]:
                if v == dst:
                    return True
                seen[v] = True
                stack.append(v)
    return False

total = 0
correct = 0
mism = []
for d in sorted(glob.glob(os.path.join(root, "*"))):
    f = os.path.join(d, "example.json")
