import json, os, re, sys
import sympy as sp

x = sp.Symbol('x', real=True)

def parse_expr(code):
    s = code
    if '=' in s:
        s = s.split('=', 1)[1]
    local = {'x': x, 'log': sp.log, 'exp': sp.exp, 'Abs': sp.Abs}
    return sp.sympify(s, locals=local)

def term_curvature(term, domain_positive):
    """Return curvature sign category of a single additive term.
    Returns 'pos', 'neg', 'zero', 'varies'.
    domain_positive: True if x>0 only.
    """
    coeff, rest = term.as_coeff_Mul()
    coeff = sp.nsimplify(coeff)
    if rest == 1:
        return 'zero'  # constant
    if coeff == 0:
        return 'zero'
    sgn = 1 if coeff > 0 else -1
    atom = rest
    # Abs
    if atom.has(sp.Abs):
        # on x>0, Abs(x)=x -> linear -> curvature zero
        # (assuming Abs(x) is the only nonlinearity; if nested, treat as convex-ish)
        if domain_positive:
            return 'zero'
        return 'pos' if sgn > 0 else 'neg'
    if atom.has(sp.exp):
        # c*exp(k x): second derivative = c k^2 exp(kx), sign = sign(c)
        return 'pos' if sgn > 0 else 'neg'
    if atom.has(sp.log):
        # c*log(x): second derivative = -c/x^2, sign = -sign(c); only valid x>0
        return 'neg' if sgn > 0 else 'pos'
    # polynomial power x**n or x
    power = None
    if atom == x:
        power = 1
    elif atom.is_Pow and atom.base == x:
        power = atom.exp
    if power is not None:
        if not power.is_integer or power < 1:
            # non-integer power etc: fall back numeric
            return 'numeric'
        n = int(power)
        if n == 1:
            return 'zero'
        if domain_positive:
            # x^(n-2) > 0 for n>=2
            return 'pos' if sgn > 0 else 'neg'
        else:
            if n % 2 == 0:
                return 'pos' if sgn > 0 else 'neg'
            else:
                return 'varies'  # odd power >=3 changes curvature sign
    return 'numeric'

def numeric_curvature(expr, domain_positive):
    f2 = sp.diff(expr, x, 2)
    import math
    # sample points
    if domain_positive:
        pts = [10**(e) for e in [i*0.25-3 for i in range(0, 29)]]  # 1e-3 .. 1e4
    else:
        pts = [0.0]
        pts += [10**(e) for e in [i*0.25-3 for i in range(0, 29)]]
        pts += [-10**(e) for e in [i*0.25-3 for i in range(0, 29)]]
    signs = set()
    for p in pts:
        try:
            v = complex(f2.subs(x, p))
        except Exception:
            continue
        if abs(v.imag) > 1e-9:
            continue
        r = v.real
        if r > 1e-9:
            signs.add(1)
        elif r < -1e-9:
            signs.add(-1)
    if signs == {1}:
        return 'convex'
    if signs == {-1}:
        return 'concave'
    if len(signs) <= 1:
        return 'convex'  # all ~0 => both convex & concave; pick convex
    return 'neither'

def classify(expr, domain_positive):
    terms = sp.Add.make_args(expr)
    cats = []
    for t in terms:
        c = term_curvature(t, domain_positive)
        if c == 'numeric':
            return numeric_curvature(expr, domain_positive)
        cats.append(c)
    nonzero = set(c for c in cats if c != 'zero')
    if 'varies' in nonzero:
        return 'neither'
    if len(nonzero) == 0:
        return numeric_curvature(expr, domain_positive)
    if len(nonzero) == 1:
        return 'convex' if 'pos' in nonzero else 'concave'
    # mixed -> neither
    return 'neither'

def main():
    d = r'datasets\develop\math_convexity'
    total = 0
    correct = 0
    wrong = []
    for name in os.listdir(d):
        p = os.path.join(d, name, 'example.json')
        if not os.path.isfile(p):
            continue
        j = json.load(open(p, encoding='utf-8'))
        dp = j.get('domain') is not None and '0' in str(j.get('domain'))
        expr = parse_expr(j['code'])
        pred = classify(expr, dp)
        total += 1
        if pred == j['label']:
            correct += 1
        else:
            wrong.append((name, j['domain'], j['code'], j['label'], pred))
    print('total', total, 'correct', correct, 'acc', correct/total)
    for w in wrong[:40]:
        print(w)

if __name__ == '__main__':
